package com.fluxisai.proposal;
import java.net.URI; import java.util.*; import com.fluxisai.common.web.PageResponse; import jakarta.validation.Valid; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.support.ServletUriComponentsBuilder;
@RestController @RequestMapping("/api/proposals") public class ProposalController { private final ProposalService service; public ProposalController(ProposalService s){service=s;} @PostMapping public ResponseEntity<ProposalResponse> create(@Valid @RequestBody ProposalRequest r){var c=service.create(r);URI location=ServletUriComponentsBuilder.fromCurrentRequest().path("/{id}").buildAndExpand(c.id()).toUri();return ResponseEntity.created(location).body(c);} @GetMapping public PageResponse<ProposalResponse> list(@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC) Pageable p){return service.list(p);} @GetMapping("/{id}") public ProposalResponse get(@PathVariable UUID id){return service.get(id);} @GetMapping("/{id}/history") public List<ProposalHistoryResponse> history(@PathVariable UUID id){return service.history(id);} @PutMapping("/{id}") public ProposalResponse update(@PathVariable UUID id,@Valid @RequestBody ProposalRequest r){return service.update(id,r);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable UUID id){service.delete(id);} }
